    CHECK(!strcmp(image.info.build,MODULE_BUILD) && !memcmp(image.data,module+64u,UF_PAYLOAD_BYTES));kui_runtime_free(&image);
    CHECK(kui_runtime_read(RAW_PATH,&image,logger,cancel)==KUI_RUNTIME_HEADER && !image.data);
