    CHECK(f_open(&file,REMOVED_PATH,FA_READ)==FR_NO_FILE && f_stat(REMOVED_PATH,&info)==FR_NO_FILE);
    CHECK(kui_update_physical_stat(REMOVED_PATH,&info)==FR_OK && info.fsize==UF_FILE_BYTES);
    CHECK(kui_update_physical_open(&file,RAW_PATH,FA_READ)==FR_OK && f_size(&file)==4u);
    uint8_t root[4];UINT got=0;
    CHECK(f_read(&file,root,sizeof(root),&got)==FR_OK && got==sizeof(root) && !memcmp(root,"root",4u));
    CHECK(f_close(&file)==FR_OK);
